import { test, expect } from '@playwright/test';

test.describe('Table Sorting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should sort the table by clicking the first column header', async ({ page }) => {
    const firstColumnHeader = page.getByRole('columnheader', { name: 'First Column' });
    await firstColumnHeader.click();

    const firstRowFirstColumn = page.getByRole('row', { name: 'Row 1' }).getByRole('cell', { name: 'Value A' });
    const secondRowFirstColumn = page.getByRole('row', { name: 'Row 2' }).getByRole('cell', { name: 'Value B' });

    await expect(firstRowFirstColumn).toBeVisible();
    await expect(secondRowFirstColumn).toBeVisible();
  });

  test('should sort the table by clicking the second column header', async ({ page }) => {
    const secondColumnHeader = page.getByRole('columnheader', { name: 'Second Column' });
    await secondColumnHeader.click();

    const firstRowSecondColumn = page.getByRole('row', { name: 'Row 1' }).getByRole('cell', { name: 'Value C' });
    const secondRowSecondColumn = page.getByRole('row', { name: 'Row 2' }).getByRole('cell', { name: 'Value D' });

    await expect(firstRowSecondColumn).toBeVisible();
    await expect(secondRowSecondColumn).toBeVisible();
  });
});
